package pl.mzebrows.pwt.net.session;

import java.io.IOException;
import java.io.InputStream;
import java.util.Properties;

/**
 * Which build this is, as far as lockstep cares: a hash of every source that decides what a tick does,
 * generated by {@code :net:generateBuildId}. Two peers with different ids are refused at the handshake
 * (ADR 0012) - the one mismatch that cannot be healed, because the same inputs would make different
 * worlds.
 */
public final class BuildId {

    private static final String RESOURCE = "pwt-build.properties";

    /** What a build that was not made by Gradle reports - and which matches nobody, not even itself. */
    static final String UNKNOWN = "unknown";

    private BuildId() {}

    /** This build's id, or {@code "unknown"} when the generated file is missing. */
    public static String current() {
        return Holder.ID;
    }

    private static final class Holder {
        static final String ID = load();

        private static String load() {
            try (InputStream stream = BuildId.class.getClassLoader().getResourceAsStream(RESOURCE)) {
                if (stream == null) {
                    return UNKNOWN;
                }
                Properties properties = new Properties();
                properties.load(stream);
                return properties.getProperty("build.id", UNKNOWN);
            } catch (IOException e) {
                return UNKNOWN;
            }
        }
    }
}
